#include "../host/scene_loader.hpp"
#include "../engine/native/animation.hpp"
#include <fstream>
#include <iostream>
#include <cstring>
int main(int argc,char** argv){unsigned checks=0;const auto check=[&](bool value,const std::string& message){++checks;if(!value)throw std::runtime_error(message);};try{
    check(argc>=4,"Expected coating scene, character and legacy character");host::SceneDocument doc;std::string error;check(host::loadScene(argv[1],doc,error),error);check(doc.scene.materials.size()>=2,"Coating materials loaded");const auto& material=doc.scene.materials[1];check(!material.coat.empty()&&!material.coatRoughness.empty()&&!material.coatNormal.empty(),"Three independent coating texture bindings");for(unsigned slot=5;slot<8;slot++)check(material.textureMappings[slot].sampler>0,"Coating mapping compiled");check(doc.scene.importedMeshes[0].hasLayerUvs,"Static optional layer streams");check(sizeof(engine::ConvexVertex)==120,"Static GPU stride");
    const auto identity=engine::gameplay::sceneIdentity(doc.scene);auto changed=doc.scene;changed.materials[1].coatNormal="other";check(engine::gameplay::sceneIdentity(changed)!=identity,"Coating texture participates in content identity");changed=doc.scene;changed.materials[1].textureMappings[7].row0[2]+=.1f;check(engine::gameplay::sceneIdentity(changed)!=identity,"Coating mapping participates in content identity");engine::Game game;game.initialize(doc.scene);game.update({},1.f/60);auto snapshot=game.snapshot();game.update({},1.f/60);game.restore(snapshot);check(game.snapshot()==snapshot,"Coating snapshot round trip");
    auto asset=engine::animation::loadAsset(argv[2]),legacy=engine::animation::loadAsset(argv[3]);check(asset->hasLayerUvs,"Character optional layer UV section");check(!legacy->hasLayerUvs,"Legacy character remains loadable");check(sizeof(engine::animation::SkinVertex)==152,"Skin GPU stride");bool nonzero=false;for(const auto& v:asset->vertices)for(const auto& uv:v.layerUvs)for(float f:uv)nonzero|=f!=0;check(nonzero,"Layer UVs reached native vertices");for(const auto& v:legacy->vertices)for(const auto& uv:v.layerUvs)for(float f:uv)check(f==0,"Legacy layer stream defaults to zero");
    nlohmann::json h;std::ifstream(argv[2])>>h;std::ifstream binaryFile(std::filesystem::path(argv[2]).parent_path()/"animation.bin",std::ios::binary);std::vector<std::uint8_t> bytes((std::istreambuf_iterator<char>(binaryFile)),{});const auto load=[&](nlohmann::json header,const std::vector<std::uint8_t>& binary){engine::determinism::Hasher hash;for(auto b:binary)hash.u8(b);header["binaryHash"]=hash.hex();auto text=header.dump();return engine::animation::loadAssetData({text.begin(),text.end()},binary);};const auto reject=[&](const nlohmann::json& header,const std::vector<std::uint8_t>& binary){bool rejected=false;try{load(header,binary);}catch(const engine::animation::Error&){rejected=true;}check(rejected,"Invalid coating UV data rejected");};auto bad=h;bad["mesh"].erase("layerUvOffset");reject(bad,bytes);bad=h;bad["mesh"]["layerUvOffset"]=0;reject(bad,bytes);bad=h;bad["mesh"]["layerUvBytes"]=1;reject(bad,bytes);
    const std::size_t at=h["mesh"]["layerUvOffset"];for(float value:{std::nanf(""),1000001.f}){auto corrupt=bytes;std::memcpy(corrupt.data()+at,&value,4);reject(h,corrupt);}auto modified=bytes;float value=.871f;std::memcpy(modified.data()+at,&value,4);check(load(h,modified)->geometryHash!=asset->geometryHash,"Layer stream participates in geometry identity");
    for(int i=4;i<argc;i++){check(!host::loadScene(argv[i],doc,error),"Invalid coating material rejected");check(engine::gameplay::sceneIdentity(doc.scene)==identity,"Material rejection is atomic");}
    std::cout<<"{\"success\":true,\"checks\":"<<checks<<"}\n";return 0;
}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
